#include "closed_transpose_arithmetic.hpp"
Class cm_rational_point_class(QuarticKM& km,const EBPoly& f,int point){
    int anchor=km.fibers[0].support[0];if(point==anchor)return km.identity;auto divisor=km.base_divisor();--divisor[anchor];++divisor[point];Space constraints;
    for(auto& [index,m]:divisor){if(!m)continue;require(m<=4,"complete rational point multiplicity4");auto& p=km.points[size_t(index)];std::vector<Z> modc(size_t(m+1),Z(0));modc[size_t(m)]=Z(1);CFPoly modulus(modc),t{Z(0),Z(1)},x{Z(p.x)},y{p.y};bool xlocal=f.partial(1).eval(Z(p.x),p.y)!=Z(0);if(xlocal)x=x+t;else{require(f.partial(0).eval(Z(p.x),p.y)!=Z(0),"complete rational point smooth chart");y=y+t;}auto derivative=f.partial(xlocal?1:0);for(int precision=1;precision<m;precision*=2){auto error=cm_curve(f,modulus,x,y),d=cm_curve(derivative,modulus,x,y);if(xlocal)y=(y-error*cm_inverse(d,modulus))%modulus;else x=(x-error*cm_inverse(d,modulus))%modulus;}require(cm_curve(f,modulus,x,y).degree()<0,"complete rational point exact jets");std::vector<CFPoly> jets;for(auto e:km.mons)jets.push_back((pc_power_mod(x,e[0],modulus)*pc_power_mod(y,e[1],modulus))%modulus);for(int order=0;order<m;++order){Vector row;for(auto& j:jets)row.push_back(j.at(order));constraints.push_back(row);}}
    require(constraints.size()==12,"complete rational point degree12");auto coefficients=nullspace(constraints,int(km.mons.size()));require(coefficients.size()==22,"complete rational point RR22");Space values;for(auto& c:coefficients)values.push_back(linear_combination(c,km.v3));return {row_basis(values,evaluation_count)};
}
struct CMEncoded {Class value;std::vector<int> auxiliary;std::array<int,3> overlap{};};
struct CMAdapter {
    QuarticKM& km;EBPoly f;std::vector<int> reference;std::array<std::vector<CFPoly>,3> jets;
    CMAdapter(QuarticKM& k,EBPoly ff,const Json& formal):km(k),f(std::move(ff)){
        for(auto& i:formal.at("seed_indices").arr){reference.push_back(i.integer());}
        require(reference.size()==3,"complete KM reference triple");CFPoly t{Z(0),Z(1)};std::vector<Z> modc(13,Z(0));modc[12]=Z(1);CFPoly modulus(modc);
        for(int r=0;r<3;++r){auto& p=km.points[size_t(reference[size_t(r)])];CFPoly x{Z(p.x)},y{p.y};bool xlocal=f.partial(1).eval(Z(p.x),p.y)!=Z(0);if(xlocal)x=x+t;else{require(f.partial(0).eval(Z(p.x),p.y)!=Z(0),"complete KM smooth reference chart");y=y+t;}auto derivative=f.partial(xlocal?1:0);for(int precision=1;precision<12;precision*=2){auto error=cm_curve(f,modulus,x,y),d=cm_curve(derivative,modulus,x,y);if(xlocal)y=(y-error*cm_inverse(d,modulus))%modulus;else x=(x-error*cm_inverse(d,modulus))%modulus;}require(cm_curve(f,modulus,x,y).degree()<0,"complete KM exact reference jets");for(auto e:km.mons)jets[size_t(r)].push_back((pc_power_mod(x,e[0],modulus)*pc_power_mod(y,e[1],modulus))%modulus);}
    }
    CMEncoded encode(const MCycle& c,int d){
        require(d>=1&&d<=3&&c.u.degree()==3*d,"complete KM cycle/source degree");require(cm_curve(f,c.u,c.x,c.y).degree()<0,"complete KM input cycle incidence");CMEncoded out;std::set<int> excluded(km.pool.begin(),km.pool.end());excluded.insert(reference.begin(),reference.end());for(int i=int(km.points.size())-1;i>=0&&out.auxiliary.size()<3;--i){auto& p=km.points[size_t(i)];if(!excluded.count(i)&&p.x!=km.fibers[0].x&&c.u.eval(Z(p.x)+Z(c.coordinate)*p.y)!=Z(0))out.auxiliary.push_back(i);}require(out.auxiliary.size()==3,"complete KM available auxiliary3");
        Space constraints(size_t(c.u.degree()),Vector(km.mons.size(),Z(0)));for(size_t j=0;j<km.mons.size();++j){auto e=km.mons[j];auto value=(pc_power_mod(c.x,e[0],c.u)*pc_power_mod(c.y,e[1],c.u))%c.u;for(int i=0;i<c.u.degree();++i)constraints[size_t(i)][j]=value.at(i);}
        for(int r=0;r<3;++r){auto& p=km.points[size_t(reference[size_t(r)])];Z z=Z(p.x)+Z(c.coordinate)*p.y;CFPoly reduced=c.u;int m=0;while(reduced.degree()>0&&reduced.eval(z)==Z(0)){reduced=reduced.exact(CFPoly{-z,Z(1)});++m;}if(m)require(c.x.eval(z)==Z(p.x)&&c.y.eval(z)==p.y,"complete KM overlapping reference coordinate");out.overlap[size_t(r)]=m;for(int order=m;order<m+3-d;++order){require(order<12,"complete KM reference jet capacity");Vector row;for(auto& jet:jets[size_t(r)])row.push_back(jet.at(order));constraints.push_back(row);}}
        for(int i:out.auxiliary){auto& p=km.points[size_t(i)];Vector row;for(auto e:km.mons)row.push_back(zpow(Z(p.x),e[0])*zpow(p.y,e[1]));constraints.push_back(row);}require(constraints.size()==12,"complete KM effective degree12 constraints");auto coeff=nullspace(constraints,int(km.mons.size()));require(coeff.size()==22,"complete KM RR dimension22");Space values;for(auto& row:coeff)values.push_back(linear_combination(row,km.v3));Class positive{row_basis(values,evaluation_count)};require(positive.w.size()==22,"complete KM evaluation dimension22");std::map<int,int> baseline;for(int i:reference)baseline[i]=3;for(int i:out.auxiliary)++baseline[i];out.value=km.add(positive,km.negate(km.effective(baseline)));return out;
    }
};
